//! Real generated bytes, typed document notices and native owner retirement.

use super::{Notice, WebViewHost, policy::Registration};
use crate::windows::webview::{
    event::{WebViewEvent, WebViewHostEvent},
    tests::TestPackage,
};
use serde::Serialize;
use std::{
    io,
    ops::Deref,
    path::PathBuf,
    time::{Duration, Instant},
};

pub(super) const URI: &str = "https://metis.invalid/index.html";

#[derive(Default, Serialize)]
pub(super) struct Document {
    rows: Vec<Notice>,
    originals: Vec<String>,
    original_bytes: usize,
}

impl Deref for Document {
    type Target = [Notice];
    fn deref(&self) -> &Self::Target {
        &self.rows
    }
}

#[derive(Serialize)]
pub(super) struct Payload {
    pub(super) directory: PathBuf,
    pub(super) files: std::collections::BTreeMap<String, usize>,
}

pub(super) fn package() -> (TestPackage, Payload) {
    let original = PathBuf::from(
        std::env::var_os("MOIRAI_WEBVIEW_KEYBOARD_FIXTURE")
            .expect("actual compiled keyboard payload"),
    )
    .canonicalize()
    .expect("actual payload directory");
    let expected = [
        "bootstrap.js",
        "favicon.svg",
        "index.html",
        "webview_keyboard_fixture.js",
        "webview_keyboard_fixture_bg.wasm",
    ];
    let mut names: Vec<_> = std::fs::read_dir(&original)
        .expect("actual payload entries")
        .map(|entry| entry.expect("payload member").file_name())
        .collect();
    names.sort();
    assert_eq!(names, expected.map(std::ffi::OsString::from));
    let mut package = TestPackage::create_with_script(
        &std::fs::read(original.join("index.html")).expect("actual generated HTML"),
    );
    let mut files = std::collections::BTreeMap::new();
    for name in expected {
        let source = original.join(name);
        assert!(
            source
                .symlink_metadata()
                .expect("payload metadata")
                .file_type()
                .is_file()
        );
        if name != "index.html" {
            std::fs::copy(&source, package.directory.join(name)).expect("actual payload copy");
        }
        let original = std::fs::read(&source).expect("original bytes");
        assert_eq!(
            original,
            std::fs::read(package.directory.join(name)).expect("copied bytes")
        );
        files.insert(name.to_owned(), original.len());
    }
    package.permit_cleanup(false);
    (
        package,
        Payload {
            directory: original,
            files,
        },
    )
}

pub(super) fn pump(
    host: &mut WebViewHost,
    registration: &Registration,
    notices: &mut Document,
    deadline: Instant,
) -> io::Result<()> {
    let remaining = deadline.saturating_duration_since(Instant::now());
    if remaining.is_zero() {
        return Err(io::Error::new(
            io::ErrorKind::TimedOut,
            "keyboard fixture original 30-second deadline",
        ));
    }
    registration.validate()?;
    for event in host.wait_events(remaining.min(Duration::from_millis(25)))? {
        if let WebViewHostEvent::WebView(WebViewEvent::Message { json, source }) = event {
            if source != URI {
                return Err(io::Error::other("keyboard notice has an unadmitted source"));
            }
            if notices.len() >= 66 {
                return Err(io::Error::other(
                    "keyboard notice count exceeds finite payload",
                ));
            }
            let bytes = notices
                .original_bytes
                .checked_add(json.len())
                .ok_or_else(|| io::Error::other("actual native notice bytes overflow"))?;
            if bytes > crate::webview_limits::MAX_WEBVIEW_MESSAGE_BYTES {
                return Err(io::Error::other(
                    "native original notice bytes exceed aggregate cap",
                ));
            }
            let value = serde_json::from_str(&json).map_err(io::Error::other)?;
            notices.original_bytes = bytes;
            notices.rows.push(value);
            notices.originals.push(json);
        }
    }
    registration.validate()
}

pub(super) fn until(
    host: &mut WebViewHost,
    registration: &Registration,
    notices: &mut Document,
    deadline: Instant,
    reached: impl Fn(&[Notice]) -> bool,
) -> io::Result<()> {
    while !reached(notices) {
        pump(host, registration, notices, deadline)?;
    }
    Ok(())
}
